// ---------------------------------------------------------------- Go renderer

// GO_INITIALISMS keeps Go's initialism style (operationIDPattern, not operationIdPattern).
const GO_INITIALISMS = new Set(["id", "ttl", "http", "json", "url", "ms"]);

function goIdent(snake) {
  const parts = snake.split("_");
  return (
    parts[0] +
    parts
      .slice(1)
      .map((p) => (GO_INITIALISMS.has(p) ? p.toUpperCase() : p ? p[0].toUpperCase() + p.slice(1) : ""))
      .join("")
  );
}

function goExported(snake) {
  const id = goIdent(snake);
  return id[0].toUpperCase() + id.slice(1);
}

function q(s) {
  return JSON.stringify(s);
}

function goStrings(values) {
  return "[]string{" + values.map(q).join(", ") + "}";
}

const GO_EXPORTED = new Set(["schema_version", "spec_version", "contract_version"]);

function renderGo(m) {
  const L = [];
  L.push(VENDOR_HEADER_GO);
  L.push("");
  L.push(GENERATED_GO);
  L.push("");
  L.push("package aicli");
  L.push("");
  for (const s of m.strings) {
    const name = GO_EXPORTED.has(s.name) ? goExported(s.name) : goIdent(s.name);
    const doc = GO_EXPORTED.has(s.name) ? s.doc : `${name}: ${s.doc}`;
    L.push(`// ${doc}`);
    L.push(`const ${name} = ${q(s.value)}`);
    L.push("");
  }
  L.push("const (");
  for (const i of m.ints) {
    L.push(`\t// ${goIdent(i.name)}: ${i.doc}`);
    L.push(`\t${goIdent(i.name)} = ${i.value}`);
  }
  L.push(")");
  L.push("");
  L.push("// codeSpec is one row of the core error-code table (contract.json error_codes.core).");
  L.push("type codeSpec struct {");
  L.push("\texit      int");
  L.push("\tretryable bool");
  L.push("\tmeaning   string");
  L.push("}");
  L.push("");
  L.push("// coreCodes maps every core error code to its exit code, retryability and meaning.");
  L.push("var coreCodes = map[string]codeSpec{");
  for (const c of m.codes) {
    L.push(`\t${q(c.name)}: {exit: ${c.exit}, retryable: ${c.retryable}, meaning: ${q(c.meaning)}},`);
  }
  L.push("}");
  L.push("");
  L.push("// exitCodeMeanings maps each documented process exit code to its meaning.");
  L.push("var exitCodeMeanings = map[int]string{");
  for (const e of m.exitCodes) L.push(`\t${e.exit}: ${q(e.meaning)},`);
  L.push("}");
  L.push("");
  L.push("// detailRule lists the detail keys an error code requires (contract.json error_details.by_code).");
  L.push("type detailRule struct {");
  L.push("\trequired      []string");
  L.push("\toptional      []string");
  L.push("\trequiredOneOf []string");
  L.push("\trequiredWhen  map[string][]string");
  L.push("}");
  L.push("");
  L.push("// detailRules maps an error code to the detail keys it must carry.");
  L.push("var detailRules = map[string]detailRule{");
  for (const r of m.detailRules) {
    const parts = [];
    if (r.required.length) parts.push(`required: ${goStrings(r.required)}`);
    if (r.optional.length) parts.push(`optional: ${goStrings(r.optional)}`);
    if (r.requiredOneOf.length) parts.push(`requiredOneOf: ${goStrings(r.requiredOneOf)}`);
    if (r.requiredWhen.length) {
      parts.push(
        "requiredWhen: map[string][]string{" + r.requiredWhen.map(([k, v]) => `${q(k)}: ${goStrings(v)}`).join(", ") + "}",
      );
    }
    L.push(`\t${q(r.code)}: {${parts.join(", ")}},`);
  }
  L.push("}");
  L.push("");
  for (const mp of m.maps) {
    L.push(`// ${goIdent(mp.name)}: ${mp.doc}`);
    L.push(`var ${goIdent(mp.name)} = map[string]string{`);
    for (const [k, v] of mp.entries) L.push(`\t${q(k)}: ${q(v)},`);
    L.push("}");
    L.push("");
  }
  L.push("var (");
  for (const l of m.lists) {
    L.push(`\t// ${goIdent(l.name)}: ${l.doc}`);
    L.push(`\t${goIdent(l.name)} = ${goStrings(l.values)}`);
  }
  L.push(")");
  return L.join("\n") + "\n";
}

// ---------------------------------------------------------------- Python renderer

// The Python module keeps every line within the template's ruff line length
// (ruff check E501 cannot be fixed by the formatter): comments are wrapped and
// long string literals are split into implicitly concatenated parts.
const PY_LINE = 100;

function pyIdent(snake) {
  return snake.toUpperCase();
}

// pyDoc adapts the model's doc strings, which name the Go file in one place.
function pyDoc(doc) {
  return doc.replace(/^[A-Z][A-Za-z]+ is the /, "The ").replace(/receipt\.go/g, "receipt.py");
}

function pyComment(text, indent = "") {
  const words = text.split(/\s+/).filter(Boolean);
  const out = [];
  let cur = indent + "#";
  for (const w of words) {
    if (cur !== indent + "#" && (cur + " " + w).length > PY_LINE) {
      out.push(cur);
      cur = indent + "# " + w;
    } else {
      cur += " " + w;
    }
  }
  out.push(cur);
  return out;
}

function pyStr(s) {
  return JSON.stringify(s);
}

// pyValue renders a string after `lead` (e.g. `    "E_X": `) and before `tail`
// (e.g. `,`): one literal when it fits, else parenthesised parts.
function pyValue(lead, s, tail) {
  const one = lead + pyStr(s) + tail;
  if (one.length <= PY_LINE) return [one];
  const indent = /^\s*/.exec(lead)[0];
  const inner = indent + "    ";
  const parts = [];
  let cur = "";
  for (const piece of s.split(/(?<= )/)) {
    if (cur && (inner + pyStr(cur + piece)).length > PY_LINE) {
      parts.push(cur);
      cur = piece;
    } else {
      cur += piece;
    }
  }
  if (cur) parts.push(cur);
  return [lead + "(", ...parts.map((p) => inner + pyStr(p)), indent + ")" + tail];
}

function pyTuple(values) {
  if (values.length === 0) return "()";
  if (values.length === 1) return `(${pyStr(values[0])},)`;
  return "(" + values.map(pyStr).join(", ") + ")";
}

function renderPy(m) {
  const L = [];
  L.push(VENDOR_HEADER_PY);
  L.push("");
  L.push(GENERATED_PY);
  L.push("");
  L.push('"""Constants of contract.json: codes, exit codes, enums, key sets and budgets."""');
  L.push("");
  L.push("from __future__ import annotations");
  L.push("");
  L.push("from typing import NamedTuple");
  L.push("");
  for (const s of m.strings) {
    L.push(...pyComment(`${pyIdent(s.name)}: ${pyDoc(s.doc)}`));
    L.push(...pyValue(`${pyIdent(s.name)} = `, s.value, ""));
    L.push("");
  }
  for (const i of m.ints) {
    L.push(...pyComment(`${pyIdent(i.name)}: ${pyDoc(i.doc)}`));
    L.push(`${pyIdent(i.name)} = ${i.value}`);
    L.push("");
  }
  L.push("");
  L.push("class CodeRow(NamedTuple):");
  L.push('    """One row of the core error-code table (contract.json error_codes.core)."""');
  L.push("");
  L.push("    exit: int");
  L.push("    retryable: bool");
  L.push("    meaning: str");
  L.push("");
  L.push("");
  L.push("# CORE_CODES maps every core error code to its exit code, retryability and meaning.");
  L.push("CORE_CODES: dict[str, CodeRow] = {");
  for (const c of m.codes) {
    L.push(`    ${pyStr(c.name)}: CodeRow(`);
    L.push(`        ${c.exit},`);
    L.push(`        ${c.retryable ? "True" : "False"},`);
    L.push(...pyValue("        ", c.meaning, ","));
    L.push("    ),");
  }
  L.push("}");
  L.push("");
  L.push("# EXIT_CODE_MEANINGS maps each documented process exit code to its meaning.");
  L.push("EXIT_CODE_MEANINGS: dict[int, str] = {");
  for (const e of m.exitCodes) L.push(...pyValue(`    ${e.exit}: `, e.meaning, ","));
  L.push("}");
  L.push("");
  L.push("");
  L.push("class DetailRule(NamedTuple):");
  L.push('    """The detail keys an error code requires (contract.json error_details.by_code)."""');
  L.push("");
  L.push("    required: tuple[str, ...] = ()");
  L.push("    optional: tuple[str, ...] = ()");
  L.push("    required_one_of: tuple[str, ...] = ()");
  L.push("    required_when: tuple[tuple[str, tuple[str, ...]], ...] = ()");
  L.push("");
  L.push("");
  L.push("# DETAIL_RULES maps an error code to the detail keys it must carry.");
  L.push("DETAIL_RULES: dict[str, DetailRule] = {");
  for (const r of m.detailRules) {
    L.push(`    ${pyStr(r.code)}: DetailRule(`);
    if (r.required.length) L.push(`        required=${pyTuple(r.required)},`);
    if (r.optional.length) L.push(`        optional=${pyTuple(r.optional)},`);
    if (r.requiredOneOf.length) L.push(`        required_one_of=${pyTuple(r.requiredOneOf)},`);
    if (r.requiredWhen.length) {
      L.push("        required_when=(");
      for (const [k, v] of r.requiredWhen) L.push(`            (${pyStr(k)}, ${pyTuple(v)}),`);
      L.push("        ),");
    }
    L.push("    ),");
  }
  L.push("}");
  L.push("");
  for (const mp of m.maps) {
    L.push(...pyComment(`${pyIdent(mp.name)}: ${pyDoc(mp.doc)}`));
    L.push(`${pyIdent(mp.name)}: dict[str, str] = {`);
    for (const [k, v] of mp.entries) L.push(...pyValue(`    ${pyStr(k)}: `, v, ","));
    L.push("}");
    L.push("");
  }
  for (const l of m.lists) {
    L.push(...pyComment(`${pyIdent(l.name)}: ${pyDoc(l.doc)}`));
    L.push(`${pyIdent(l.name)}: tuple[str, ...] = (`);
    for (const v of l.values) L.push(...pyValue("    ", v, ","));
    L.push(")");
    L.push("");
  }
  while (L.length && L[L.length - 1] === "") L.pop();
  return L.join("\n") + "\n";
}

// ---------------------------------------------------------------- main

function parseArgs(argv) {
  const a = { lang: "", out: "", contract: "", check: false };
  for (let i = 0; i < argv.length; i++) {
    const k = argv[i];
    const value = () => {
      if (i + 1 >= argv.length) throw new Error(`gen-contract: ${k} needs a value`);
      return argv[++i];
    };
    if (k === "--lang") a.lang = value();
    else if (k === "--out") a.out = value();
    else if (k === "--contract") a.contract = value();
    else if (k === "--check") a.check = true;
    else if (k === "-h" || k === "--help") a.help = true;
    else throw new Error(`gen-contract: unknown argument ${k}`);
  }
  return a;
}

function usage() {
  return "usage: gen-contract.js [--lang " + Object.keys(LANGS).join("|") + "] [--check] [--contract <path>] [--out <file>]";
}

function main() {
  const a = parseArgs(process.argv.slice(2));
  if (a.help) {
    console.log(usage());
    return 0;
  }
  if (a.lang && !LANGS[a.lang]) {
    console.error(`gen-contract: unknown --lang ${a.lang}\n${usage()}`);
    return 2;
  }
  if (!a.lang && !a.check) {
    console.error(`gen-contract: give --lang to generate, or --check to verify every language\n${usage()}`);
    return 2;
  }
  if (a.out && !a.lang) {
    console.error("gen-contract: --out needs --lang");
    return 2;
  }
  const contractPath = a.contract || DEFAULT_CONTRACT;
  const contract = JSON.parse(fs.readFileSync(contractPath, "utf8"));
  const model = buildModel(contract);
  const langs = a.lang ? [a.lang] : Object.keys(LANGS);
  let drift = 0;
  for (const lang of langs) {
    const spec = LANGS[lang];
    const outPath = a.out || spec.out;
    const content = spec.format(spec.render(model));
    if (a.check) {
      const existing = fs.existsSync(outPath) ? fs.readFileSync(outPath, "utf8").replace(/\r\n/g, "\n") : null;
      if (existing !== content) {
        console.error(`[check] DRIFT: ${outPath} does not match ${contractPath}. Run: node ${path.relative(process.cwd(), __filename)} --lang ${lang}`);
        drift++;
      } else {
        console.log(`[check] OK: ${outPath}`);
      }
      continue;
    }
    fs.mkdirSync(path.dirname(outPath), { recursive: true });
    fs.writeFileSync(outPath, content);
    console.log(`generated ${outPath} (${model.codes.length} error codes)`);
  }
  return drift ? 1 : 0;
}

if (require.main === module) {
  try {
    process.exitCode = main();
  } catch (err) {
    console.error(String((err && err.message) || err));
    process.exitCode = 2;
  }
}

module.exports = { buildModel, renderGo, renderPy, LANGS };
